KG42.register("rules-efa4cb8595e97d8de83b37d3",{"id":"20-storage_sharing_auction::v141-c-R004","paper":"20-storage_sharing_auction","record":{"rule_id":"v141-c-R004","mechanism_id":"v141-a-M01","name":"Counterparty matching","process_stage":"matching","market_meaning":"The auctioneer determines the preliminary participating SFC and RU groups through cutoff counts K and J obtained from the intersection of the aggregate supply and demand curves. Scope: Community joint energy-storage ownership auction; determination of preliminary participant cutoffs before marginal-participant exclusion. Condition: The supply–demand intersection cutoffs satisfy a_K ≥ r_J. RUs outside {1, 2, ..., J} and SFCs outside {1, 2, ..., K} are removed from the auction process. Scope: Community joint energy-storage ownership auction; exclusion of parties beyond the intersection cutoffs. Condition: After K and J are determined, a_m \u003c r_i for every SFC outside {1, 2, ..., K} and RU outside {1, 2, ..., J}. The joint storage-sharing group is restricted to K − 1 SFCs and J − 1 RUs, excluding the marginal SFC K and RU J. Scope: Community joint energy-storage ownership auction; participant-group restriction for a truthful auction. Condition: J and K have been determined and auction truthfulness is required. SFC K and RU J may also participate in the joint storage-sharing trading group. Scope: Community joint energy-storage ownership auction; optional inclusion of marginal participants. Condition: A truthful auction is not a necessity.","independence_rationale":"Relations governed by the approved function matching.counterparties under the fixed relation-ownership template. Conditional branches retain their explicit scope in local constraints.","V":["coordination.local_operator","matching.counterparties"],"E":[{"edge_id":"v141-c-R004-E001","source":"coordination.local_operator","target":"matching.counterparties","type":"links","constraint_ids":["v141-c-R004-C001"],"evidence_ids":["v141-b-g02-E01","v141-b-g02-E05"]}],"omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"matching","context_text":"Community joint energy-storage ownership auction; determination of preliminary participant cutoffs before marginal-participant exclusion. | Community joint energy-storage ownership auction; exclusion of parties beyond the intersection cutoffs. | Community joint energy-storage ownership auction; optional inclusion of marginal participants. | Community joint energy-storage ownership auction; participant-group restriction for a truthful auction.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g02-E01","v141-b-g02-E05","v141-b-g02-E06","v141-b-g02-E07","v141-b-g02-E08"]},"x":[{"variable_id":"v141-c-R004-x-K","symbol":"K","meaning":"Number of participating SFCs determined by the auctioneer from the intersection of the aggregate supply and demand curves; cutoff count for the SFC side of the matching stage.","kind":"operational","domain":"K \\in \\{1,\\ldots,M\\}","unit":"SFCs","indices":[],"evidence_ids":["v141-b-g02-E05","v141-b-g01-E32"]},{"variable_id":"v141-c-R004-x-J","symbol":"J","meaning":"Number of participating RUs determined by the auctioneer from the intersection of the aggregate supply and demand curves; cutoff count for the RU side of the matching stage.","kind":"operational","domain":"J \\in \\{1,\\ldots,N\\}","unit":"RUs","indices":[],"evidence_ids":["v141-b-g02-E05","v141-b-g01-E32"]}],"theta":[{"parameter_id":"v141-c-R004-theta-a-m","symbol":"a_m","meaning":"Reservation bid of SFC m, i.e. the maximum per-unit price SFC m is willing to pay for sharing ES with the RUs; used in the ordered SFC bids and the matching inequalities.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":"price per unit of energy","indices":["m \\in M"],"evidence_ids":["v141-b-g02-E04","v141-b-g01-E10"]},{"parameter_id":"v141-c-R004-theta-r-i","symbol":"r_i","meaning":"Reservation price per unit of energy set by RU i; used in the ordered RU reservation prices and the matching inequalities.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":"price per unit of energy","indices":["i \\in N"],"evidence_ids":["v141-b-g02-E04","v141-b-g01-E09"]}],"phi":[{"constraint_id":"v141-c-R004-C001","kind":"mathematical","role":"core","statement":"The auctioneer determines the preliminary participating SFC and RU groups through cutoff counts K and J obtained from the intersection of the aggregate supply and demand curves. Scope: Community joint energy-storage ownership auction; determination of preliminary participant cutoffs before marginal-participant exclusion. Condition: The supply–demand intersection cutoffs satisfy a_K ≥ r_J.","expression":"a_K \\ge r_J","formalization_origin":"source","template_id":null,"members":["coordination.local_operator","matching.counterparties"],"variable_refs":["v141-c-R004-x-K","v141-c-R004-x-J"],"parameter_refs":["v141-c-R004-theta-a-m","v141-c-R004-theta-r-i"],"evidence_ids":["v141-b-g02-E01","v141-b-g02-E05"]},{"constraint_id":"v141-c-R004-C002","kind":"mathematical","role":"core","statement":"RUs outside {1, 2, ..., J} and SFCs outside {1, 2, ..., K} are removed from the auction process. Scope: Community joint energy-storage ownership auction; exclusion of parties beyond the intersection cutoffs. Condition: After K and J are determined, a_m \u003c r_i for every SFC outside {1, 2, ..., K} and RU outside {1, 2, ..., J}.","expression":"a_m \u003c r_i \\quad \\forall m \\in M \\setminus \\{1,2,\\ldots,K\\},\\ \\forall i \\in N \\setminus \\{1,2,\\ldots,J\\}","formalization_origin":"source","template_id":null,"members":["matching.counterparties"],"variable_refs":["v141-c-R004-x-K","v141-c-R004-x-J"],"parameter_refs":["v141-c-R004-theta-a-m","v141-c-R004-theta-r-i"],"evidence_ids":["v141-b-g02-E06"]},{"constraint_id":"v141-c-R004-C003","kind":"mathematical","role":"core","statement":"The joint storage-sharing group is restricted to K − 1 SFCs and J − 1 RUs, excluding the marginal SFC K and RU J. Scope: Community joint energy-storage ownership auction; participant-group restriction for a truthful auction. Condition: J and K have been determined and auction truthfulness is required.","expression":"\\mathcal{S}^{\\mathrm{truthful}}_{\\mathrm{SFC}} = \\{1,\\ldots,K-1\\},\\quad \\mathcal{S}^{\\mathrm{truthful}}_{\\mathrm{RU}} = \\{1,\\ldots,J-1\\}","formalization_origin":"source","template_id":null,"members":["matching.counterparties"],"variable_refs":["v141-c-R004-x-K","v141-c-R004-x-J"],"parameter_refs":[],"evidence_ids":["v141-b-g02-E07","v141-b-g02-E08"]},{"constraint_id":"v141-c-R004-C004","kind":"procedural","role":"core","statement":"SFC K and RU J may also participate in the joint storage-sharing trading group. Scope: Community joint energy-storage ownership auction; optional inclusion of marginal participants. Condition: A truthful auction is not a necessity.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["matching.counterparties"],"variable_refs":["v141-c-R004-x-K","v141-c-R004-x-J"],"parameter_refs":[],"evidence_ids":["v141-b-g02-E08"]}],"pi":[{"evidence_id":"v141-b-g02-E01","location":{"location_id":"src-441686b1ee-p04-c2r3__v141-a-M01-participation","page":4,"printed_page":null,"section":"IV. Auction Based ES Ownership","anchor_text":"er- nality properties, as we will see later, which are desirable in he any mechanism that adopts auc","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"1) Owner: The RUs in set N, which own the ES devices, and expect to earn some economic benefits, e.g., through maximizing a utility function, by letting the SFCs to share some fraction of their ES spaces. 2) Customer: The SFCs in set M, which are in need of ESs in order to store some excess electricity at a particular time of the day. The SFCs offer the RUs a price with a view to jointly owning some fraction of their ES devices. 3) Auctioneer: A third party (e.g., estate or building manager), which controls the auction process between the owners and the customers according to some predefined rules."},{"evidence_id":"v141-b-g02-E05","location":{"location_id":"src-441686b1ee-p05-c1r4__v141-a-M01-bidding","page":5,"printed_page":null,"section":"IV-A. Determination Rule","anchor_text":"the quantity qm ∀m of ES that they require. wo iii) Once the auctioneer receives the ordered informa","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"definition"},"source_text":"iii) Once the auctioneer receives the ordered information from the RUs and the SFCs, it generates the aggregated supply (reservation price of the RUs versus the amount of ES the RUs are interested in sharing) and demand curves (reservation bids a_m verses the quantity of ES q_m needed) using (2) and (3) respectively. iv) The auctioneer determines the numbers of participating SFCs K and RUs J that satisfy a_K \\ge r_J from the intersection of the two curves using any standard numerical method [44]."},{"evidence_id":"v141-b-g02-E06","location":{"location_id":"src-441686b1ee-p05-c2r1__v141-a-M01-participation","page":5,"printed_page":null,"section":"IV-A. Determination Rule","anchor_text":"IEEE TRANSACTIONS ON SMART GRID, VOL. 7, NO. 3, MAY 2016 of ESs. We note that once the numbers of SF","equation_id":"(4)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"condition"},"source_text":"We note that once the numbers of SFCs K and RUs J are determined, the following relationship holds for the rest of the SFCs and RUs in the network: a_m \u003c r_i; \\forall m \\in M/\\{1, 2, ..., K\\}, \\forall i \\in N/\\{1, 2, ..., J\\}. (4) Hence, the joint ownership of ES would be a detrimental choice for the RUs and the SFCs within the set N/\\{1, 2, ..., J\\} and M/\\{1, 2, ..., K\\} respectively, which consequently remove them from the proposed auction process."},{"evidence_id":"v141-b-g02-E07","location":{"location_id":"src-441686b1ee-p05-c2r2__v141-a-M01-participation","page":5,"printed_page":null,"section":"IV-A. Determination Rule","anchor_text":"p p y y no participating agents in the auction mechanism will cheat once the payment and allocation ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"condition"},"source_text":"To this end, we propose that, once J and K are determined, K −1 SFCs and J −1 RUs will be engaged in the joint ES sharing process, which is a necessary condition for matching total demand and supply while maintaining a truthful auction scheme [44]."},{"evidence_id":"v141-b-g02-E08","location":{"location_id":"src-441686b1ee-p05-c2r2__v141-a-M01-participation","page":5,"printed_page":null,"section":"IV-A. Determination Rule","anchor_text":"p p y y no participating agents in the auction mechanism will cheat once the payment and allocation ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"condition"},"source_text":"Nevertheless, if a truthful auction is not a necessity, then SFC K and RU J can also be allowed to participate in the joint ES ownership auction."},{"evidence_id":"v141-b-g01-E09","location":{"location_id":"src-441686b1ee-p03-c2r3__v141-a-M01-bidding","page":3,"printed_page":null,"section":"III. System Model","anchor_text":"DR the sharing is attractive for it. di is the amount of ES that he the RU does not want to share, b","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"definition"},"source_text":"To this end, to offer an ES space $x_i$, on the one hand, each RU $i$ decides on an reservation price $r_i$ per unit of energy. Hereinafter, we will use ES space and energy interchangeably to refer to the ES space that each RU might share with the SFCs. However, if the price $p_t$, which each RU received for sharing its ES, is lower than $r_i$, the RU $i$ removes its ES space $x_i$ from the market as the expected benefit from the joint sharing of ES is not economically attractive for it."},{"evidence_id":"v141-b-g01-E10","location":{"location_id":"src-441686b1ee-p03-c2r4__v141-a-M01-bidding","page":3,"printed_page":null,"section":"III. System Model","anchor_text":"hat willing to pay for sharing of ES with the RUs in the smart re community, to enter into the shari","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"definition"},"source_text":"On the other hand, each SFC $m \\in \\mathcal{M}$, that needs to share ES space with the RUs to store their energy, decides a reservation bid $a_m$, which represents the maximum per unit price the SFC $m$ is willing to pay for sharing of ES with the RUs in the smart community, to enter into the sharing market."},{"evidence_id":"v141-b-g01-E32","location":{"location_id":"src-441686b1ee-p05-c1r4__v141-a-M01-bidding","page":5,"printed_page":null,"section":"IV-A. Determination Rule","anchor_text":"the quantity qm ∀m of ES that they require. wo iii) Once the auctioneer receives the ordered informa","equation_id":null,"figure_id":"Fig. 3","table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"condition"},"source_text":"The auctioneer determines the numbers of participating SFCs $K$ and RUs $J$ that satisfy $a_K \\ge r_J$ from the intersection of the two curves using any standard numerical method [44]. As soon as the SFC $K \\le M$ and RU $J \\le N$ are determined from the intersection point, as shown in Fig. 3, an important aspect of the auction mechanism is to determine the number of SFCs and RUs, that will take part in the joint ownership of ESs."},{"evidence_id":"v141-b-g02-E04","location":{"location_id":"src-441686b1ee-p05-c1r3__v141-a-M01-bidding","page":5,"printed_page":null,"section":"IV-A. Determination Rule","anchor_text":"the The determination rule of the proposed scheme is executed Hovia the following steps (inspired fr","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"formula"},"source_text":"i) The RUs of set \\mathcal{N}, i.e., the owners of the ESs, declare their reservation prices r_i, \\forall i in an increasing order, which we can consider, without loss of generality, as r_1 \u003c r_2 \u003c ... \u003c r_N. (2) The RUs submit the reservation price along with the amount x_i of ES that they are interested in sharing with the SFCs to the auctioneer. ii) The SFCs' bidding prices, i.e., a_m, \\forall m, are arranged in a decreasing order, i.e., a_1 > a_2 > ... > a_M. (3) The SFCs submit their bids to the auctioneer along with the quantity q_m \\forall m of ES that they require."}],"field_notes":{"empty_E_reason":null,"empty_x_reason":null,"empty_theta_reason":null},"evidence_basis":"explicit","implementation_status":"unimplemented","status":"needs_review","lead_ids":["v141-a-M01-bidding","v141-a-M01-participation"],"extras":{"decision_anchor":"matching.counterparties","graph_fact_supports":[[{"evidence_id":"v141-b-g02-E05","quote":"The auctioneer determines the numbers of participating SFCs K and RUs J that satisfy a_K \\ge r_J from the intersection of the two curves using any standard numerical method [44]."},{"evidence_id":"v141-b-g02-E01","quote":"3) Auctioneer: A third party (e.g., estate or building manager), which controls the auction process between the owners and the customers according to some predefined rules."}],[{"evidence_id":"v141-b-g02-E06","quote":"a_m \u003c r_i; \\forall m \\in M/\\{1, 2, ..., K\\}, \\forall i \\in N/\\{1, 2, ..., J\\}. (4) Hence, the joint ownership of ES would be a detrimental choice for the RUs and the SFCs within the set N/\\{1, 2, ..., J\\} and M/\\{1, 2, ..., K\\} respectively, which consequently remove them from the proposed auction process."}],[{"evidence_id":"v141-b-g02-E07","quote":"once J and K are determined, K −1 SFCs and J −1 RUs will be engaged in the joint ES sharing process, which is a necessary condition for matching total demand and supply while maintaining a truthful auction scheme [44]."},{"evidence_id":"v141-b-g02-E08","quote":"Nevertheless, if a truthful auction is not a necessity, then SFC K and RU J can also be allowed to participate in the joint ES ownership auction."}],[{"evidence_id":"v141-b-g02-E08","quote":"Nevertheless, if a truthful auction is not a necessity, then SFC K and RU J can also be allowed to participate in the joint ES ownership auction."}]],"C2_formalization":{"graph_sha256":"315d9b1155987da9d813c6ca1d21b948acdf705b6408ab11c1b96bff18a9dc3c","applicability":"formalized","reason":"The source states explicit matching conditions: a_K ≥ r_J for the auctioneer's cutoff determination, the exclusion inequality (4) for SFCs/RUs beyond the cutoffs, and the truthful-auction cardinalities K−1 and J−1. These are formalized with declared cutoff variables K,J and bid/price parameters a_m,r_i. C004 is an optional permission ('can also be allowed') and is left unformalized. B evidence remains unreviewed; no independent source audit is claimed.","bindings":[{"object_id":"v141-c-R004-x-K","node_ids":["matching.counterparties"],"edge_ids":["v141-c-R004-E001"],"rationale":"K is the SFC cutoff count produced in the auctioneer's matching step; edge E001 links the local operator's determination to counterparty matching."},{"object_id":"v141-c-R004-x-J","node_ids":["matching.counterparties"],"edge_ids":["v141-c-R004-E001"],"rationale":"J is the RU cutoff count produced in the auctioneer's matching step; edge E001 links the local operator's determination to counterparty matching."},{"object_id":"v141-c-R004-theta-a-m","node_ids":["matching.counterparties"],"edge_ids":[],"rationale":"a_m is the SFC reservation bid used by the matching inequalities; the frozen graph has no separate SFC-bid edge, so it is attached to matching.counterparties."},{"object_id":"v141-c-R004-theta-r-i","node_ids":["matching.counterparties"],"edge_ids":[],"rationale":"r_i is the RU reservation price used by the matching inequalities; no separate RU-bid edge exists in the frozen graph."},{"object_id":"v141-c-R004-C001","node_ids":["coordination.local_operator","matching.counterparties"],"edge_ids":["v141-c-R004-E001"],"rationale":"C001 is the auctioneer's determination of cutoff counts K and J at the supply-demand intersection; the local operator performs this step through counterparty matching, as recorded by edge E001."},{"object_id":"v141-c-R004-C002","node_ids":["matching.counterparties"],"edge_ids":[],"rationale":"C002 specifies which SFCs/RUs beyond the cutoff sets are removed from the matching stage; it is a condition inside matching.counterparties, with no separate edge in the frozen graph."},{"object_id":"v141-c-R004-C003","node_ids":["matching.counterparties"],"edge_ids":[],"rationale":"C003 restricts the engaged truthful-auction groups to K−1 SFCs and J−1 RUs, a participant-set restriction within matching.counterparties."}],"revision_requests":[]}},"quarantined_references":[]}});
